'use strict';
const $=id=>document.getElementById(id),H=SCMHub,I=SCMImport,S=SCMSnapshot,esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),fmt=v=>typeof v==='number'?v.toLocaleString('ko-KR'):'—';let active=null,db=null,dictionary=[],staged=[],busy=false,lastSnapshot;
function notice(message,type=''){const el=$('notice');el.textContent=message;el.className='data-notice '+type}
async function action(fn){if(busy)return;busy=true;for(const id of ['selectDb','selectFiles','useSample','applyFiles','restoreData','downloadDb','saveMappings'])$(id).disabled=true;try{await fn()}catch(e){notice(e.message,'error');console.error(e)}finally{busy=false;for(const id of ['selectDb','selectFiles','useSample','applyFiles','restoreData','downloadDb','saveMappings'])$(id).disabled=false}}
function download(bytes,name,type='application/octet-stream'){const url=URL.createObjectURL(new Blob([bytes],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
async function refresh(){const record=await H.get();active=record;if(db){db.close();db=null}if(!record){$('currentLabel').textContent='연결된 DB 없음';$('dataSummary').innerHTML='';$('sourceStatus').innerHTML=I.TYPES.map(t=>`<tr><td>${t.kind}</td><td>—</td><td>0</td><td>0</td><td>미연결</td></tr>`).join('');$('mappingRows').innerHTML='<tr><td colspan="5">위치별 재고현황이 연결되면 설정할 수 있습니다.</td></tr>';$('qualitySummary').textContent='';$('qualityDetails').innerHTML='';return}const SQL=await H.sql();db=new SQL.Database(record.bytes);H.check(db);lastSnapshot=S.read(db);$('currentLabel').textContent=(record.meta.name||'내 SCM DB')+' · '+new Date(record.meta.updatedAt).toLocaleString('ko-KR',{timeZone:'Asia/Seoul'});const p=lastSnapshot;$('dataSummary').innerHTML=[['연결 상품',p.products.length],['상품 재고 기준일',p.anchor||'없음'],['위치 행',p.positions.length],['연결 자료',p.summaries.filter(t=>t.count).length+' / 6']].map(([label,value])=>`<div><span>${label}</span><strong>${esc(typeof value==='number'?fmt(value):value)}</strong></div>`).join('');$('sourceStatus').innerHTML=p.summaries.map(t=>`<tr><td>${t.kind}</td><td>${t.latest||'—'}</td><td>${fmt(t.latestCount)}</td><td>${fmt(t.count)}</td><td>${t.count?(t.latest===p.anchor?'같은 기준일':'기준일 다름'):'미연결'}</td></tr>`).join('');const issues=H.rows(db,'SELECT COUNT(*) AS n FROM data_issues')[0].n;$('qualitySummary').textContent='상품 재고 중복 기준키 '+p.duplicates+'개 · 상품정보 미연결 '+p.missingMaster+'개 · 위치 상품 미연결 '+p.unlinkedPositions+'행 · 층/코드 미배정 '+p.unmapped+'행 · 같은 날짜 재고 합계 불일치 '+p.mismatch+'개 · 적재 점검 기록 '+issues+'건. 다른 날짜의 위치 재고는 상품 재고와 합산하지 않습니다.';
const detail=H.rows(db,'SELECT source_file_id,source_row_number,column_name,issue_type,original_value FROM data_issues ORDER BY issue_id DESC LIMIT 30');$('qualityDetails').innerHTML=detail.length?'<details><summary>최근 적재 점검 기록 보기 · 최대 30건</summary><pre>'+esc(detail.map(r=>JSON.stringify(r)).join('\n'))+'</pre></details>':'';renderMappings()}
function renderMappings(){$('mappingRows').innerHTML=lastSnapshot?.locationGroups.length?lastSnapshot.locationGroups.map((g,index)=>`<tr><td>${esc(g.warehouse||'—')}</td><td>${esc([g.rawFloor||'층 없음',g.rawZone||'존 없음',g.area||'구역 없음'].join(' / '))}<small class="destination-code">${g.saved?'저장한 설정':'원본 층 사용 / 보관존 분류'}</small></td><td>${g.count}</td><td><select aria-label="가상 층 ${index+1}" data-map-floor="${index}">${[0,1,2,3,4].map(f=>`<option value="${f}" ${g.target_floor===f?'selected':''}>${f?f+'층':'미배정'}</option>`).join('')}</select></td><td><select aria-label="가상 보관 구역 ${index+1}" data-map-zone="${index}">${Object.entries(S.ZONE_NAMES).map(([code,name])=>`<option value="${code}" ${g.target_zone===code?'selected':''}>${name}</option>`).join('')}</select></td></tr>`).join(''):'<tr><td colspan="5">연결된 위치 재고가 없습니다.</td></tr>'}
async function parseFile(file){if(file.size>30*1024*1024)throw Error(file.name+': 원본 파일은 30MB 이하로 나누어 주세요.');const bytes=new Uint8Array(await file.arrayBuffer()),hash=[...new Uint8Array(await crypto.subtle.digest('SHA-256',bytes))].map(x=>x.toString(16).padStart(2,'0')).join('');if(/\.xlsx$/i.test(file.name)){const workbook=new ExcelJS.Workbook();try{await workbook.xlsx.load(bytes)}catch(e){throw Error(file.name+': XLSX를 읽지 못했습니다. 암호를 해제하거나 CSV로 저장해 주세요.')}const out=[];for(const sheet of workbook.worksheets){if(sheet.actualRowCount>250001)throw Error('한 시트는 25만 행 이하로 나누어 주세요.');if(sheet.actualColumnCount>500)throw Error('칼럼이 500개를 초과하는 시트입니다.');if(!sheet.actualRowCount)continue;const matrix=[];sheet.eachRow({includeEmpty:true},row=>{const values=[];for(let i=1;i<=sheet.actualColumnCount;i++){const cell=row.getCell(i);let v=cell.value;if(v instanceof Date)v=v.toISOString().replace('T',' ').replace(/ 00:00:00.000Z$/,'').replace(/\.000Z$/,'');else if(v&&typeof v==='object'){if(v.formula||v.sharedFormula){if(v.result===undefined)throw Error(file.name+': 계산 결과가 없는 수식 셀이 있습니다. 값으로 저장해 주세요.');v=v.result}else if(v.richText)v=v.richText.map(t=>t.text).join('');else if(v.text!==undefined)v=v.text;else if(v.error)v=null;else v=String(v)}if(typeof v==='number'&&Number.isInteger(v)&&Math.abs(v)>=1e15)throw Error(file.name+': 16자리 이상 숫자 셀이 있습니다. ID를 텍스트로 저장해 주세요.');if(typeof v==='number'&&/입점|일자|매입일|기준일/.test(String(matrix[0]?.[i-1]||''))&&v>20000&&v<100000)v=new Date(Date.UTC(1899,11,30)+Math.round(v)*86400000).toISOString().slice(0,10);values.push(v??'')}matrix.push(values)});out.push({file,bytes,hash,name:file.name+' / '+sheet.name,encoding:'xlsx',matrix})}return out}let encoding='utf-8',text;try{text=new TextDecoder('utf-8',{fatal:true}).decode(bytes)}catch(e){text=new TextDecoder('euc-kr',{fatal:true}).decode(bytes);encoding='cp949'}return [{file,bytes,hash,name:file.name,encoding,matrix:I.csv(text)}]}
function filenameDate(name){const m=name.match(/(20\d{2})[-_.]?(\d{2})[-_.]?(\d{2})/);return m?I.date(m[1]+'-'+m[2]+'-'+m[3]):null}
function evaluateStage(item){try{item.prepared=I.prepare(item.matrix,item.kind,dictionary,item.headerRow);item.error=''}catch(e){item.prepared=null;item.error=e.message}}
function renderStaging(){$('staging').hidden=!staged.length;$('stagingRows').innerHTML=staged.map((item,index)=>`<tr><td>${esc(item.name)}<small>${item.encoding} · ${fmt(item.matrix.length)}행</small></td><td><select data-stage="${index}" data-field="kind" aria-label="자료 유형 ${index+1}"><option value="">유형 선택</option>${I.TYPES.map(t=>`<option value="${t.kind}" ${t.kind===item.kind?'selected':''}>${t.kind}</option>`).join('')}</select></td><td><input type="number" min="1" max="20" value="${item.headerRow+1}" data-stage="${index}" data-field="headerRow" aria-label="헤더 행 ${index+1}"></td><td><input type="date" value="${item.date}" data-stage="${index}" data-field="date" aria-label="파일 기준일 ${index+1}"></td><td>${item.error?'<span class="warning-text">'+esc(item.error)+'</span>':`<b>${fmt(item.prepared.records.length)}행 · ${item.prepared.mapping.length}칼럼 연결</b><small>미매핑 ${item.prepared.unknown.length}칼럼 · 숫자 오류 ${item.prepared.issues.length}건</small>${item.prepared.unknown.length?'<small class="warning-text">'+esc(item.prepared.unknown.slice(0,5).join(', '))+'</small>':''}`}</td></tr>`).join('');$('stagingRows').querySelectorAll('[data-stage]').forEach(el=>el.onchange=()=>{const item=staged[Number(el.dataset.stage)];item[el.dataset.field]=el.dataset.field==='headerRow'?Math.max(0,Math.min(19,Number(el.value)-1)):el.value;evaluateStage(item);renderStaging()})}
$('selectDb').onclick=()=>$('databaseFile').click();$('selectFiles').onclick=()=>$('sourceFiles').click();$('databaseFile').onchange=()=>{const file=$('databaseFile').files[0];$('databaseFile').value='';if(!file)return;action(async()=>{notice('DB 구조와 연결키를 확인하고 있습니다.','busy');if(file.size>100*1024*1024)throw Error('DB는 100MB 이하로 선택해 주세요.');const bytes=new Uint8Array(await file.arrayBuffer()),SQL=await H.sql(),candidate=new SQL.Database(bytes);try{H.check(candidate);S.read(candidate)}finally{candidate.close()}const previous=await H.get();await H.save(bytes,{name:file.name,source:'db',synthetic:false},previous?.revision||null);await refresh();notice('내 DB를 연결했습니다. SQL 분석실과 물류센터가 같은 DB를 읽습니다. 실제 층·존 배치를 아래에서 확인하세요.')})};
$('sourceFiles').onchange=()=>{const files=[...$('sourceFiles').files];$('sourceFiles').value='';if(!files.length)return;action(async()=>{if(files.reduce((n,f)=>n+f.size,0)>80*1024*1024)throw Error('한 번에 선택하는 원본 파일 합계는 80MB 이하로 나누어 주세요.');notice('원본 파일과 칼럼을 검사하고 있습니다.','busy');const next=[];for(const f of files)for(const item of await parseFile(f)){const detected=I.detect(item.matrix,dictionary,item.name);Object.assign(item,{kind:detected.kind,headerRow:detected.headerRow,date:filenameDate(item.name)||new Date(Date.now()+9*3600000).toISOString().slice(0,10)});evaluateStage(item);next.push(item)}staged=next;renderStaging();notice('파일 유형·기준일·인식 결과를 확인한 뒤 연결 반영을 누르세요. 아직 현재 DB는 바뀌지 않았습니다.')})};
$('applyFiles').onclick=()=>action(async()=>{if(!staged.length||staged.some(item=>item.error||!item.prepared))throw Error('인식 오류가 있는 파일의 유형과 헤더 행을 먼저 확인해 주세요.');notice('연결 원장을 만들고 SQL 무결성을 검사하고 있습니다.','busy');const previous=await H.get(),append=$('importMode').value==='append';if(append&&!previous)throw Error('추가할 연결 DB가 없습니다. 새 원장 만들기를 선택하세요.');if(append&&previous.meta.synthetic)throw Error('동봉 가상 DB와 실제 자료를 섞을 수 없습니다. 새 원장 만들기를 선택하세요.');const SQL=await H.sql(),candidate=new SQL.Database(append?previous.bytes:await H.template(true));let result,bytes;try{result=I.apply(candidate,staged.map(item=>({name:item.name,bytes:item.bytes,encoding:item.encoding,hash:item.hash,date:item.date,prepared:item.prepared})),{replace:$('replaceChanged').checked});H.check(candidate);bytes=candidate.export()}finally{candidate.close()}await H.save(bytes,{name:'내 SCM 원장 · '+new Date(Date.now()+9*3600000).toISOString().slice(0,10),source:'files',synthetic:false},previous?.revision||null);await refresh();notice('연결 반영 완료 · '+result.imported+'개 자료 / '+fmt(result.rows)+'행 추가, 동일 파일 '+result.skipped+'개 건너뜀. SQL 분석실과 물류센터에서 확인할 수 있습니다.');staged=[];renderStaging()});
$('useSample').onclick=()=>action(async()=>{notice('동봉 가상 DB를 두 화면에 연결하고 있습니다.','busy');const previous=await H.get();await H.save(await H.template(),{name:'동봉 가상 SCM DB',source:'synthetic',synthetic:true},previous?.revision||null);await refresh();notice('가상 DB가 연결되었습니다. 실제 파일 없이 연결과 배치 설정을 시험할 수 있습니다.')});$('clearStaging').onclick=()=>{staged=[];renderStaging();notice('파일 선택을 취소했습니다.')};$('refreshData').onclick=()=>action(async()=>{await refresh();notice('현재 연결 상태를 새로 확인했습니다.')});$('restoreData').onclick=()=>action(async()=>{await H.restore();await refresh();notice('이전 연결 데이터를 복원했습니다.')});$('downloadDb').onclick=()=>action(async()=>{const record=await H.get();if(!record)throw Error('먼저 데이터를 연결하세요.');download(record.bytes,'scm_connected.db');notice('원본 자료와 배치 설정을 포함한 연결 DB를 저장했습니다.')});
$('saveMappings').onclick=()=>action(async()=>{if(!db||!lastSnapshot?.locationGroups.length)throw Error('위치별 재고현황을 먼저 연결하세요.');const groups=lastSnapshot.locationGroups.map((g,index)=>({...g,target_floor:Number(document.querySelector('[data-map-floor="'+index+'"]').value),target_zone:document.querySelector('[data-map-zone="'+index+'"]').value})),SQL=await H.sql(),candidate=new SQL.Database(active.bytes);let bytes;try{S.saveMappings(candidate,groups);bytes=candidate.export()}finally{candidate.close()}await H.save(bytes,active.meta,active.revision);await refresh();notice('층·보관 구역 배치를 반영했습니다. 원본 위치 칼럼은 그대로 보존했습니다.')});
H.subscribe(record=>{if(!busy&&record.revision!==active?.revision)action(async()=>{await refresh();notice('다른 화면에서 변경한 연결 DB를 반영했습니다.')})});action(async()=>{dictionary=(await fetch('schema.json').then(r=>r.json())).dictionary;await refresh();notice(active?'연결된 DB를 불러왔습니다. 두 화면에서 같은 데이터를 사용합니다.':'내 SCM DB 또는 원본 자료를 선택하세요. 처음에는 동봉 가상 DB로도 시험할 수 있습니다.')});
